import{_ as a,c as i,a as n,o as d}from"./app--u3Uwk-L.js";const r={};function c(t,e){return d(),i("div",null,e[0]||(e[0]=[n('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-09-14-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-09-14-资讯日报"><span>2026-09-14 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="奥特曼被骗-a社偷偷冲刺ipo" tabindex="-1"><a class="header-anchor" href="#奥特曼被骗-a社偷偷冲刺ipo"><span>奥特曼被骗 A社偷偷冲刺IPO</span></a></h3><p>Anthropic一边喊AI危险要踩刹车，一边加速冲IPO，募资对标SpaceX欲破美股纪录，14个月估值涨16倍；奥特曼刚跟进呼吁安全，转头称此时上市不明智。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9d9241de383ac854f90220f0da2d5a34143d4350a9fa8de8210575acfa9748056df430ffe9b&amp;idx=2&amp;mid=2247922638&amp;sn=b84b9d7db386d0fbd0dc461d50de0b43#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="李柏依eccv-机器人还得学会听" tabindex="-1"><a class="header-anchor" href="#李柏依eccv-机器人还得学会听"><span>李柏依ECCV：机器人还得学会听</span></a></h3><p>NVIDIA李柏依提出，机器人仅靠视觉感知不够，加入声音能提升系统鲁棒性，针对训练数据采集难，可用生成补仿真声音、从人类视频提取操作数据解决。<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=91215abd1ef5ae2494c0be061f3e72d437f9a7945b142679239b068fc1b7b90cf7074d7e2007&amp;idx=2&amp;mid=2247745263&amp;sn=502f7b6c7d03e2005c32de78d4e5013d#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="dario抛出ai全球共管计划" tabindex="-1"><a class="header-anchor" href="#dario抛出ai全球共管计划"><span>Dario抛出AI全球共管计划</span></a></h3><p>Dario Amodei称AI发展过快风险极高，拒绝将AI控制权交予单一政府，呼吁全球多国共管AI；业内质疑巨头借AI安全炒作，靠监管垒高壁垒变相垄断，挤走中小竞争者。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0806b8703366a4508ebb73aa7ddb213f793888ec6a0ad36f794f597272461854e8503fb17e2&amp;idx=1&amp;mid=2652725517&amp;sn=ed44ef22c1e8dc04d3b21d47a570acfc#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="qwen3-8-max搭建ai合同精审系统" tabindex="-1"><a class="header-anchor" href="#qwen3-8-max搭建ai合同精审系统"><span>Qwen3.8-Max搭建AI合同精审系统</span></a></h3><p>作者基于Qwen3.8-Max搭建AI合同精审系统，实测50页合同AI仅需约5分钟、成本0.5元，检出31个问题，效率和问题检出率远超人工，可作中小企业合同初审工具。<a href="https://mp.weixin.qq.com/s?__biz=MzA4MTk3ODI2OA==&amp;chksm=8614259aa15616330c50dc8f2efca6bcbb12c657bcd260293cdc39f129d6c14242941f1f8217&amp;idx=1&amp;mid=2650365338&amp;sn=b58fbe443dc7d1f6bbc5a141b6b610e2#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="mcp没死-新版规范三大变化解读" tabindex="-1"><a class="header-anchor" href="#mcp没死-新版规范三大变化解读"><span>MCP没死，新版规范三大变化解读</span></a></h3><p>作者称网传“MCP已死”不实，新版MCP围绕企业需求完成三大核心升级，MCP+Tasks适合边界清晰的长时工具调用，A2A适配复杂多轮Agent协作，两者可搭配使用。<a href="https://mp.weixin.qq.com/s?__biz=Mzk1NzQ1ODk5NQ==&amp;chksm=c2cec86549c85200517172e0ce4c05853875dab35cdcd5c8cc800b35d6bbc5fa4e451ab930a6&amp;idx=1&amp;mid=2247526359&amp;sn=895d94420fad7df1d06fb8acf79bbcd9#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="ai创作者didi-ok巅峰新作《糖果》" tabindex="-1"><a class="header-anchor" href="#ai创作者didi-ok巅峰新作《糖果》"><span>AI创作者DiDi_OK巅峰新作《糖果》</span></a></h3><p>顶尖AI影像创作者DiDi_OK推出新作《糖果》，借助Seedance 2.5实现了AI影像叙事精度与定制化的突破。他认为创作核心是创作者的审美判断，AI降低表达成本后，创作的平庸更无借口。<a href="https://mp.weixin.qq.com/s?__biz=MzIyMzA5NjEyMA==&amp;chksm=f14cd2cce34c5d6fa03730d2aa39df7278cdee55f16e919870ab7f2116aab166f5bc6a378a7a&amp;idx=1&amp;mid=2647686222&amp;sn=2b570842f213cc90ddaa3603ab7746ab#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="github千星项目-开源并行科研agent" tabindex="-1"><a class="header-anchor" href="#github千星项目-开源并行科研agent"><span>GitHub千星项目：开源并行科研Agent</span></a></h3><p>alphaXiv团队开源千星项目OpenResearch，解决现有AI编码工具不适合科研流程的痛点，将四款主流AI编码工具包装为可并行运行的科研Agent，用git特性隔离多Agent、管理实验，适配全科研工作流。<a href="https://mp.weixin.qq.com/s?__biz=MzkwMjQ0NzI0OQ==&amp;chksm=c1cadfebf5960f19bcffae622e81152f9d00c648e77d59d430c50ebb21e5a886827e4642ecf6&amp;idx=1&amp;mid=2247506937&amp;sn=b2e757b1ad33a08b6265897a54a7d80f#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="metarsi开启rsi平方时代" tabindex="-1"><a class="header-anchor" href="#metarsi开启rsi平方时代"><span>MetaRSI开启RSI平方时代</span></a></h3><p>CosmosMind联合多校发布MetaRSI-v1，这是全球首个统一三类RSI的元递归架构，让30亿激活参数小模型平均提分10.9，六款旗舰大模型平均提分7.3，开启RSI平方时代。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e93343f4aee06ea8e5171a1e404c062c98ed54c523a19f35f723a2fdd7e1bbcd035bdd524b52&amp;idx=1&amp;mid=2247922638&amp;sn=2772d27d040e39c71eb19b5d780e47c3#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',25)]))}const p=a(r,[["render",c]]),l=JSON.parse('{"path":"/posts/2026-09-14.html","title":"AI日报：奥特曼被骗 A社偷偷冲刺IPO; 李柏依ECCV：机器人还得学会听; Dario抛出AI全球共管计划","lang":"zh-CN","frontmatter":{"date":"2026-09-14T00:00:00.000Z","title":"AI日报：奥特曼被骗 A社偷偷冲刺IPO; 李柏依ECCV：机器人还得学会听; Dario抛出AI全球共管计划"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"奥特曼被骗 A社偷偷冲刺IPO","slug":"奥特曼被骗-a社偷偷冲刺ipo","link":"#奥特曼被骗-a社偷偷冲刺ipo","children":[]},{"level":3,"title":"李柏依ECCV：机器人还得学会听","slug":"李柏依eccv-机器人还得学会听","link":"#李柏依eccv-机器人还得学会听","children":[]},{"level":3,"title":"Dario抛出AI全球共管计划","slug":"dario抛出ai全球共管计划","link":"#dario抛出ai全球共管计划","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"Qwen3.8-Max搭建AI合同精审系统","slug":"qwen3-8-max搭建ai合同精审系统","link":"#qwen3-8-max搭建ai合同精审系统","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"MCP没死，新版规范三大变化解读","slug":"mcp没死-新版规范三大变化解读","link":"#mcp没死-新版规范三大变化解读","children":[]},{"level":3,"title":"AI创作者DiDi_OK巅峰新作《糖果》","slug":"ai创作者didi-ok巅峰新作《糖果》","link":"#ai创作者didi-ok巅峰新作《糖果》","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"GitHub千星项目：开源并行科研Agent","slug":"github千星项目-开源并行科研agent","link":"#github千星项目-开源并行科研agent","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"MetaRSI开启RSI平方时代","slug":"metarsi开启rsi平方时代","link":"#metarsi开启rsi平方时代","children":[]}]}],"git":{"updatedTime":1789463450000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"cebe2637b14036c2f68716177bcf307b8091e50c","time":1789463450000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-09-15T09:10:50.106Z"}]},"filePathRelative":"posts/2026-09-14.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-09-14 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>奥特曼被骗 A社偷偷冲刺IPO</h3>\\n<p>Anthropic一边喊AI危险要踩刹车，一边加速冲IPO，募资对标SpaceX欲破美股纪录，14个月估值涨16倍；奥特曼刚跟进呼吁安全，转头称此时上市不明智。<a href=\\"https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9d9241de383ac854f90220f0da2d5a34143d4350a9fa8de8210575acfa9748056df430ffe9b&amp;idx=2&amp;mid=2247922638&amp;sn=b84b9d7db386d0fbd0dc461d50de0b43#rd\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">&gt;阅读原文</a></p>"}');export{p as comp,l as data};
